#include <algorithm>
#include <iostream>

struct Wrapper {
    int val; 
    int id; // Distinguishing feature, not used in comparison
    bool operator<(const Wrapper& other) const { 
        return val < other.val; 
    }
};

int main() {
    Wrapper w1 = {10, 1}; // ID 1
    Wrapper w2 = {10, 2}; // ID 2

    // w1 == w2 via operator< (Tie)
    const Wrapper& result_min = std::min(w1, w2);

    // Output depends on the specific implementation's tie break
    // (e.g., often returns w1)
    std::cout << "Min ID (should not rely on this): " << result_min.id << "\n";

    // Correct usage: only rely on the value, not the identity
    if (result_min.val == 10) {
        // Logic is safe
    }
}
